package com.myeshopping.scheduler;
import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.scheduling.annotation.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; import java.util.concurrent.*;
@SpringBootApplication @EnableScheduling @RestController @RequestMapping("/api/v1/jobs") public class SchedulerApplication { private final Map<String,Map<String,Object>> jobs=new ConcurrentHashMap<>(); public static void main(String[]a){SpringApplication.run(SchedulerApplication.class,a);} @PostMapping public Map<String,Object> create(@RequestParam String name,@RequestParam(defaultValue="true") boolean enabled){Map<String,Object>j=new ConcurrentHashMap<>();j.put("name",name);j.put("enabled",enabled);j.put("lastRun",null);jobs.put(name,j);return j;} @PostMapping("/{name}/run") public Map<String,Object> run(@PathVariable String name){Map<String,Object>j=Optional.ofNullable(jobs.get(name)).orElseThrow(()->new IllegalArgumentException("Job not found"));if(Boolean.TRUE.equals(j.get("enabled")))j.put("lastRun",Instant.now());return j;} @GetMapping public Collection<Map<String,Object>> all(){return jobs.values();} }
